// Project Progress Monitoring and Analytics
// Real-time project tracking with predictive insights

const progressData = $input.first().json;

// Extract progress update information
const {
  projectId,
  updateType = 'status', // status, milestone, issue, completion, quality_check
  phase = 'planning', // planning, design, permitting, rough_in, inspection, trim, final
  completedTasks = [],
  issues = [],
  qualityMetrics = {},
  timeTracking = {},
  costTracking = {},
  teamUpdates = [],
  customerFeedback = null,
  timestamp = new Date().toISOString(),
  reportedBy = 'system'
} = progressData;

// Project phase definitions and typical durations
const projectPhases = {
  planning: {
    name: 'Project Planning',
    typicalDuration: 3, // days
    dependencies: [],
    deliverables: ['project_scope', 'material_list', 'timeline'],
    milestones: ['scope_approved', 'permits_submitted']
  },
  design: {
    name: 'Electrical Design',
    typicalDuration: 5,
    dependencies: ['planning'],
    deliverables: ['electrical_plans', 'load_calculations', 'panel_schedule'],
    milestones: ['design_complete', 'engineer_approval']
  },
  permitting: {
    name: 'Permit & Approval',
    typicalDuration: 10,
    dependencies: ['design'],
    deliverables: ['building_permit', 'electrical_permit', 'inspection_schedule'],
    milestones: ['permits_approved', 'inspection_scheduled']
  },
  rough_in: {
    name: 'Rough-In Installation',
    typicalDuration: 8,
    dependencies: ['permitting'],
    deliverables: ['conduit_installation', 'wire_pulling', 'box_installation'],
    milestones: ['rough_in_complete', 'rough_inspection_passed']
  },
  inspection: {
    name: 'Inspections',
    typicalDuration: 2,
    dependencies: ['rough_in'],
    deliverables: ['inspection_reports', 'correction_list'],
    milestones: ['inspection_passed', 'corrections_complete']
  },
  trim: {
    name: 'Trim & Finish',
    typicalDuration: 6,
    dependencies: ['inspection'],
    deliverables: ['device_installation', 'fixture_installation', 'panel_labeling'],
    milestones: ['trim_complete', 'system_testing']
  },
  final: {
    name: 'Final & Closeout',
    typicalDuration: 3,
    dependencies: ['trim'],
    deliverables: ['final_inspection', 'system_documentation', 'customer_training'],
    milestones: ['final_inspection_passed', 'project_closed']
  }
};

// Calculate overall project progress
function calculateProjectProgress(currentPhase, completedTasks, issues) {
  const phaseOrder = ['planning', 'design', 'permitting', 'rough_in', 'inspection', 'trim', 'final'];
  const currentPhaseIndex = phaseOrder.indexOf(currentPhase);

  if (currentPhaseIndex === -1) {
    return { overallProgress: 0, phaseProgress: 0, status: 'unknown' };
  }

  // Calculate completed phases
  const phasesCompleted = currentPhaseIndex;
  const totalPhases = phaseOrder.length;

  // Calculate current phase progress based on deliverables
  const currentPhaseInfo = projectPhases[currentPhase];
  const phaseDeliverables = currentPhaseInfo.deliverables;
  const completedDeliverables = completedTasks.filter(task => 
    phaseDeliverables.includes(task.taskId) && task.status === 'completed'
  ).length;

  const phaseProgress = phaseDeliverables.length > 0 ? 
    (completedDeliverables / phaseDeliverables.length) * 100 : 0;

  // Calculate overall progress
  const overallProgress = ((phasesCompleted + (phaseProgress / 100)) / totalPhases) * 100;

  // Determine project status
  let status = 'on_track';
  const criticalIssues = issues.filter(issue => issue.severity === 'critical').length;
  const majorIssues = issues.filter(issue => issue.severity === 'major').length;

  if (criticalIssues > 0) {
    status = 'critical';
  } else if (majorIssues > 2) {
    status = 'at_risk';
  } else if (overallProgress < 10) {
    status = 'delayed';
  }

  return {
    overallProgress: Math.round(overallProgress * 10) / 10,
    phaseProgress: Math.round(phaseProgress * 10) / 10,
    currentPhase,
    phasesCompleted,
    totalPhases,
    status,
    nextPhase: currentPhaseIndex < totalPhases - 1 ? phaseOrder[currentPhaseIndex + 1] : null
  };
}

// Analyze timeline performance
function analyzeTimelinePerformance(phase, timeTracking, projectPhases) {
  const performance = {
    currentPhase: phase,
    onSchedule: true,
    daysSpent: 0,
    estimatedDays: projectPhases[phase]?.typicalDuration || 0,
    variance: 0,
    projectedCompletion: null,
    risks: []
  };

  if (timeTracking && timeTracking.phaseStartDate) {
    const startDate = new Date(timeTracking.phaseStartDate);
    const now = new Date();
    performance.daysSpent = Math.ceil((now.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24));
    performance.variance = performance.daysSpent - performance.estimatedDays;

    if (performance.variance > 2) {
      performance.onSchedule = false;
      performance.risks.push({
        type: 'schedule_delay',
        severity: performance.variance > 5 ? 'high' : 'medium',
        description: `Current phase running ${performance.variance} days behind schedule`
      });
    }

    // Project completion estimate
    const remainingPhases = Object.keys(projectPhases).slice(
      Object.keys(projectPhases).indexOf(phase) + 1
    );

    const remainingDays = remainingPhases.reduce((sum, phaseName) => 
      sum + projectPhases[phaseName].typicalDuration, 0
    );

    const projectedDate = new Date(now.getTime() + (remainingDays * 24 * 60 * 60 * 1000));
    performance.projectedCompletion = projectedDate.toISOString().split('T')[0];
  }

  return performance;
}

// Analyze cost performance
function analyzeCostPerformance(costTracking, phase) {
  const performance = {
    budgetStatus: 'on_budget',
    actualCost: costTracking.actualCost || 0,
    budgetedCost: costTracking.budgetedCost || 0,
    variance: 0,
    variancePercentage: 0,
    burnRate: 0,
    projectedOverrun: 0,
    alerts: []
  };

  if (performance.budgetedCost > 0) {
    performance.variance = performance.actualCost - performance.budgetedCost;
    performance.variancePercentage = (performance.variance / performance.budgetedCost) * 100;

    if (performance.variancePercentage > 10) {
      performance.budgetStatus = 'over_budget';
      performance.alerts.push({
        type: 'budget_overrun',
        severity: performance.variancePercentage > 20 ? 'high' : 'medium',
        message: `Project ${performance.variancePercentage.toFixed(1)}% over budget`
      });
    } else if (performance.variancePercentage < -5) {
      performance.budgetStatus = 'under_budget';
    }
  }

  // Calculate burn rate
  if (costTracking.timeSpent > 0) {
    performance.burnRate = performance.actualCost / costTracking.timeSpent; // Cost per day
  }

  return performance;
}

// Analyze quality metrics
function analyzeQualityMetrics(qualityMetrics, issues, completedTasks) {
  const analysis = {
    overallScore: 0,
    inspectionResults: qualityMetrics.inspectionResults || [],
    defectRate: 0,
    reworkRate: 0,
    complianceScore: qualityMetrics.complianceScore || 100,
    qualityTrends: [],
    recommendations: []
  };

  // Calculate defect rate
  const totalTasks = completedTasks.length;
  const defectiveTasks = issues.filter(issue => issue.type === 'quality_issue').length;
  analysis.defectRate = totalTasks > 0 ? (defectiveTasks / totalTasks) * 100 : 0;

  // Calculate rework rate
  const reworkTasks = completedTasks.filter(task => task.reworkRequired).length;
  analysis.reworkRate = totalTasks > 0 ? (reworkTasks / totalTasks) * 100 : 0;

  // Calculate overall quality score
  const defectPenalty = Math.min(analysis.defectRate * 2, 30); // Max 30 point penalty
  const reworkPenalty = Math.min(analysis.reworkRate * 1.5, 20); // Max 20 point penalty
  const compliancePenalty = Math.max(0, 100 - analysis.complianceScore);

  analysis.overallScore = Math.max(0, 100 - defectPenalty - reworkPenalty - compliancePenalty);

  // Generate recommendations
  if (analysis.defectRate > 5) {
    analysis.recommendations.push({
      priority: 'high',
      area: 'quality_control',
      action: 'Implement additional quality checkpoints and training'
    });
  }

  if (analysis.reworkRate > 10) {
    analysis.recommendations.push({
      priority: 'medium',
      area: 'process_improvement',
      action: 'Review installation procedures and provide additional training'
    });
  }

  return analysis;
}

// Analyze team performance
function analyzeTeamPerformance(teamUpdates, completedTasks) {
  const analysis = {
    productivity: 'normal',
    tasksPerDay: 0,
    teamMorale: 'neutral',
    skillGaps: [],
    workloadDistribution: {},
    recommendations: []
  };

  if (teamUpdates && teamUpdates.length > 0) {
    // Analyze task completion rate
    const recentTasks = completedTasks.filter(task => {
      const taskDate = new Date(task.completedAt || task.createdAt);
      const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
      return taskDate >= weekAgo;
    });

    analysis.tasksPerDay = recentTasks.length / 7;

    if (analysis.tasksPerDay > 5) {
      analysis.productivity = 'high';
    } else if (analysis.tasksPerDay < 2) {
      analysis.productivity = 'low';
      analysis.recommendations.push({
        priority: 'medium',
        area: 'productivity',
        action: 'Investigate productivity bottlenecks and provide support'
      });
    }

    // Analyze workload distribution
    teamUpdates.forEach(update => {
      const memberId = update.teamMember || 'unknown';
      if (!analysis.workloadDistribution[memberId]) {
        analysis.workloadDistribution[memberId] = {
          tasksAssigned: 0,
          tasksCompleted: 0,
          utilization: 0
        };
      }

      analysis.workloadDistribution[memberId].tasksAssigned += update.tasksAssigned || 0;
      analysis.workloadDistribution[memberId].tasksCompleted += update.tasksCompleted || 0;
    });

    // Calculate utilization rates
    Object.keys(analysis.workloadDistribution).forEach(memberId => {
      const member = analysis.workloadDistribution[memberId];
      member.utilization = member.tasksAssigned > 0 ? 
        (member.tasksCompleted / member.tasksAssigned) * 100 : 0;
    });
  }

  return analysis;
}

// Generate predictive insights
function generatePredictiveInsights(progress, timeline, cost, quality, team) {
  const insights = {
    successProbability: 85, // Base probability
    riskFactors: [],
    recommendations: [],
    alerts: []
  };

  // Analyze risk factors
  if (progress.status === 'critical') {
    insights.successProbability -= 30;
    insights.riskFactors.push('Critical issues present');
  } else if (progress.status === 'at_risk') {
    insights.successProbability -= 15;
    insights.riskFactors.push('Multiple major issues');
  }

  if (!timeline.onSchedule) {
    const schedulePenalty = Math.min(timeline.variance * 2, 20);
    insights.successProbability -= schedulePenalty;
    insights.riskFactors.push(`Schedule delay: ${timeline.variance} days`);
  }

  if (cost.budgetStatus === 'over_budget') {
    const budgetPenalty = Math.min(Math.abs(cost.variancePercentage) / 2, 15);
    insights.successProbability -= budgetPenalty;
    insights.riskFactors.push(`Budget overrun: ${cost.variancePercentage.toFixed(1)}%`);
  }

  if (quality.overallScore < 80) {
    insights.successProbability -= 10;
    insights.riskFactors.push('Quality issues detected');
  }

  if (team.productivity === 'low') {
    insights.successProbability -= 10;
    insights.riskFactors.push('Low team productivity');
  }

  // Ensure probability stays within bounds
  insights.successProbability = Math.max(10, Math.min(95, insights.successProbability));

  // Generate recommendations
  if (insights.successProbability < 70) {
    insights.recommendations.push({
      priority: 'urgent',
      action: 'Immediate project review and intervention required',
      impact: 'high'
    });
  } else if (insights.successProbability < 85) {
    insights.recommendations.push({
      priority: 'high',
      action: 'Address identified risk factors to improve success probability',
      impact: 'medium'
    });
  }

  return insights;
}

// Process the progress update
const progressCalculation = calculateProjectProgress(phase, completedTasks, issues);
const timelineAnalysis = analyzeTimelinePerformance(phase, timeTracking, projectPhases);
const costAnalysis = analyzeCostPerformance(costTracking, phase);
const qualityAnalysis = analyzeQualityMetrics(qualityMetrics, issues, completedTasks);
const teamAnalysis = analyzeTeamPerformance(teamUpdates, completedTasks);
const predictiveInsights = generatePredictiveInsights(
  progressCalculation, timelineAnalysis, costAnalysis, qualityAnalysis, teamAnalysis
);

// Create comprehensive progress report
const report = {
  projectId,
  updateId: `PU-${Date.now()}`,
  timestamp,
  updateType,
  reportedBy,

  progress: progressCalculation,
  timeline: timelineAnalysis,
  cost: costAnalysis,
  quality: qualityAnalysis,
  team: teamAnalysis,
  insights: predictiveInsights,

  currentSnapshot: {
    phase: phase,
    completedTasks: completedTasks.length,
    activeIssues: issues.filter(i => i.status !== 'resolved').length,
    teamMembers: teamUpdates.length,
    customerSatisfaction: customerFeedback?.rating || null
  },

  nextActions: [
    ...predictiveInsights.recommendations,
    ...qualityAnalysis.recommendations,
    ...teamAnalysis.recommendations
  ].slice(0, 5), // Top 5 actions

  milestones: {
    upcoming: projectPhases[phase]?.milestones || [],
    nextPhase: progressCalculation.nextPhase,
    estimatedCompletion: timelineAnalysis.projectedCompletion
  },

  alerts: [
    ...costAnalysis.alerts,
    ...timelineAnalysis.risks.map(risk => ({
      type: risk.type,
      severity: risk.severity,
      message: risk.description
    })),
    ...predictiveInsights.alerts
  ],

  metadata: {
    generatedBy: 'ElectricalAI Pro Progress Monitor',
    version: '1.3.0',
    confidenceLevel: insights.successProbability > 80 ? 'high' : insights.successProbability > 60 ? 'medium' : 'low'
  }
};

return [{ json: report }];

// Generate dashboard update for real-time monitoring
const progressData = $('Save Progress Update').first().json;

// Create dashboard-optimized data structure
const dashboardUpdate = {
  projectId: progressData.projectId,
  timestamp: progressData.timestamp,

  // Key metrics for dashboard cards
  metrics: {
    progress: {
      overall: progressData.progress.overallProgress,
      phase: progressData.progress.phaseProgress,
      status: progressData.progress.status,
      currentPhase: progressData.progress.currentPhase
    },
    timeline: {
      onSchedule: progressData.timeline.onSchedule,
      daysSpent: progressData.timeline.daysSpent,
      variance: progressData.timeline.variance,
      projectedCompletion: progressData.timeline.projectedCompletion
    },
    budget: {
      status: progressData.cost.budgetStatus,
      variance: progressData.cost.variancePercentage,
      actualCost: progressData.cost.actualCost,
      budgetedCost: progressData.cost.budgetedCost
    },
    quality: {
      score: progressData.quality.overallScore,
      defectRate: progressData.quality.defectRate,
      complianceScore: progressData.quality.complianceScore
    },
    team: {
      productivity: progressData.team.productivity,
      tasksPerDay: progressData.team.tasksPerDay,
      utilization: Object.values(progressData.team.workloadDistribution)
        .reduce((avg, member, _, arr) => avg + member.utilization / arr.length, 0)
    }
  },

  // Risk indicators
  risks: {
    successProbability: progressData.insights.successProbability,
    riskLevel: progressData.insights.successProbability > 80 ? 'low' : 
               progressData.insights.successProbability > 60 ? 'medium' : 'high',
    activeAlerts: progressData.alerts.length,
    criticalIssues: progressData.currentSnapshot.activeIssues
  },

  // Recent activities
  activities: [
    {
      type: 'progress_update',
      message: `Project ${progressData.progress.overallProgress.toFixed(1)}% complete`,
      timestamp: progressData.timestamp,
      priority: 'info'
    },
    ...progressData.alerts.slice(0, 3).map(alert => ({
      type: alert.type,
      message: alert.message,
      timestamp: progressData.timestamp,
      priority: alert.severity
    })),
    ...progressData.nextActions.slice(0, 2).map(action => ({
      type: 'recommendation',
      message: action.action,
      timestamp: progressData.timestamp,
      priority: action.priority
    }))
  ],

  // Quick stats for widgets
  quickStats: {
    tasksCompleted: progressData.currentSnapshot.completedTasks,
    daysInPhase: progressData.timeline.daysSpent,
    teamMembers: progressData.currentSnapshot.teamMembers,
    customerRating: progressData.currentSnapshot.customerSatisfaction
  },

  // Next milestones
  upcomingMilestones: progressData.milestones.upcoming.map(milestone => ({
    name: milestone,
    phase: progressData.progress.currentPhase,
    estimatedDate: progressData.timeline.projectedCompletion
  })),

  // Charts data
  chartData: {
    progressTrend: {
      labels: ['Week 1', 'Week 2', 'Week 3', 'Current'],
      data: [25, 45, 70, progressData.progress.overallProgress] // Simplified trend
    },
    budgetBurn: {
      actual: progressData.cost.actualCost,
      budgeted: progressData.cost.budgetedCost,
      remaining: Math.max(0, progressData.cost.budgetedCost - progressData.cost.actualCost)
    },
    qualityTrend: {
      current: progressData.quality.overallScore,
      target: 95,
      defectRate: progressData.quality.defectRate
    }
  }
};

return [{ json: dashboardUpdate }];

// Format final response for API consumers
const progressData = $('Save Progress Update').first().json;
const dashboardData = $('Generate Dashboard Update').first().json;

const response = {
  success: true,
  projectId: progressData.projectId,
  updateId: progressData.updateId,

  summary: {
    overallProgress: progressData.progress.overallProgress,
    currentPhase: progressData.progress.currentPhase,
    status: progressData.progress.status,
    successProbability: progressData.insights.successProbability
  },

  performance: {
    timeline: {
      onSchedule: progressData.timeline.onSchedule,
      variance: progressData.timeline.variance,
      projectedCompletion: progressData.timeline.projectedCompletion
    },
    budget: {
      status: progressData.cost.budgetStatus,
      variancePercentage: progressData.cost.variancePercentage,
      remainingBudget: Math.max(0, progressData.cost.budgetedCost - progressData.cost.actualCost)
    },
    quality: {
      score: progressData.quality.overallScore,
      defectRate: progressData.quality.defectRate,
      complianceScore: progressData.quality.complianceScore
    }
  },

  alerts: progressData.alerts.map(alert => ({
    type: alert.type,
    severity: alert.severity,
    message: alert.message
  })),

  recommendations: progressData.nextActions.slice(0, 3).map(action => ({
    priority: action.priority,
    action: action.action,
    impact: action.impact || 'medium'
  })),

  milestones: {
    upcoming: progressData.milestones.upcoming,
    nextPhase: progressData.milestones.nextPhase,
    estimatedCompletion: progressData.milestones.estimatedCompletion
  },

  team: {
    productivity: progressData.team.productivity,
    tasksPerDay: progressData.team.tasksPerDay,
    memberCount: progressData.currentSnapshot.teamMembers
  },

  dashboard: {
    updated: true,
    metrics: dashboardData.quickStats,
    riskLevel: dashboardData.risks.riskLevel
  },

  timestamp: progressData.timestamp
};

return [{ json: response }];
